const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  const htmlPath = 'file://' + path.resolve('/app/output/PYPL-infographic.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Set viewport to portrait aspect ratio (A4 proportions)
  await page.setViewport({ width: 794, height: 1123 });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true
  });

  await browser.close();
  console.log('Poster saved to /app/output/final_poster.png');
})();

